该文档为国网重庆市电力公司出具的电费账单，账单周期为2026年5月1日至5月31日，打印日期为2026年6月3日。用电客户为重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10千伏，属市场化零售客户，由璧城供电服务中心供电，用电地址位于重庆市璧山区青杠街道莲花社区。本期电量为666074千瓦时，本期电费合计496365.66元，交费截止日期为2026年6月9日。

费用构成方面，账单分为工商业电费与居民电费两大部分。工商业电费电量656088千瓦时、金额494399.89元，由五部分组成：(1)市场化购电费294563.18元（含零售交易电费286054.38元及零售损益分摊电费8508.8元，零售交易电价统一为0.436元/千瓦时）；(2)上网环节线损费用11747.26元；(3)输配电费132267.52元，其中按2000千伏安容量、22元/千伏安标准计收的容量电费为44000元；(4)系统运行费24530.47元，涵盖煤电容量电费17732.09元、燃气机组容量电费11117.41元、电价交叉补贴新增损益-19903.09元等项目；(5)政府性基金及附加31291.46元。居民电费按定比0.015计费，电量9986千瓦时、金额5292.58元。此外，功率因数调整电费为-3326.81元。

用能分析显示：本期电量环比下降9.65%；尖峰平谷分时比例为3.64%、20.45%、33.52%、42.39%，与上期基本相当（账单附有对比柱状图佐证）；实际功率因数为0.96，高于0.90的标准值，较上期略降0.01，故获得电费下调调整；平均电价为0.74521元/千瓦时，较上期上涨0.01853元/千瓦时。

