协议编号：
甲方：重庆佳苑浩庭民宿经营管理有限公司
乙方：重庆星达铜业有限公司
为共同提高商务活动的便捷性，甲乙双方本着友好合作，互惠互利的原则，经双方友好协商，甲方就为乙
方提供酒店客房事宜，达成一致，并制定协议如下：
一、 房间预订特别优惠
 甲乙双方签订本协议后，乙方可享有的具体优惠如下：
三、 结算方式
1、所有房价已包含服务费，且为含税价。若乙方额外享受甲方酒店的收费服务项目需额外付费（此额外付费服务
项目以甲方酒店的明文规定为准）。
2、支付方式：由乙方入住客人通过网络预定时在线支付或离店时自行结清所有费用，甲方根据实付金额为其开具
相应发票。
四、 合作期限
本协议合作期限自 2026 年 1 月 1 日至 2026 年 1 2 月 31日止。
五、 纠纷解决
与本协议有关的任何争议，双方通过友好协商解决。如协商不成，任何一方可将此争议提交有管辖权的人民法
院诉讼。本协议适用中华人民共和国法律。
六、 协议适用范围
1、乙方关联公司亦可享受本协议项下的各项优惠措施，包括但不限于折扣优惠等。
2、乙方及乙方关联公司不得以任何方式（包括但不限于：提供卡号等）准予旅行社、会展公司及任何具有盈
利性质的差旅公司享有本合同约定的甲方及甲方关联公司享有的权利。一经发现，甲方有权立即将乙方及乙方关联
公司享受的原折扣价格降级至92折不含早餐的价格，且不再给予乙方及乙方关联公司更优惠的折扣。
3、仅乙方员工或乙方关联公司人员可享受本协议约定的优惠。乙方员工或乙方关联公司人员入住甲方酒店时，
房型 门市价 协议价（含双早）
高级大床房 339元 258元
高级双床房 359元 258元
商务大床房 369元 288元
舒压商务双床房 389元 288元
舒压山景大床房 409元 318元
豪华套房 599元 388元
会议室 2500元/天 1500元/天

甲方酒店有权对于入住人员是否属于乙方员工或乙方关联公司人员进行验证核实， 该乙方入住人员应当向甲方酒店
出示工牌、 名片或其他等可以表明其为乙方员工或乙方关联公司人员身份的证明， 否则， 该入住人员入住甲方酒店
的， 不得享受本协议约定的优惠， 同时甲方酒店有权要求该入住人员即时结算支付住宿费用。
七、 其他
1、 甲乙双方均需对本协议内容承担保密责任， 未经对方许可， 不得向第三方披露。
2、 本协议壹式貮份， 甲方执壹份， 乙方执壹份， 自双方盖章之日起生效。
（以下无正文）
